<script setup>
import {computed,onMounted,onUnmounted,reactive,ref,nextTick} from 'vue'
import {ElMessage} from 'element-plus'
import {ElMessageBox} from 'element-plus'
import axios from 'axios'
import MarkdownIt from 'markdown-it'
import DOMPurify from 'dompurify'
import RichTextEditor from './components/RichTextEditor.vue'
import CoreWorkspace from './components/CoreWorkspace.vue'
import RecordDetailDialog from './components/RecordDetailDialog.vue'
import * as echarts from 'echarts/core'
import {BarChart, LineChart} from 'echarts/charts'
import {GridComponent, TooltipComponent} from 'echarts/components'
import {CanvasRenderer} from 'echarts/renderers'
import {LayoutDashboard,FolderKanban,CheckSquare,FileText,Bug,ChartNoAxesCombined,Search,Bell,Plus,ChevronDown,ArrowUpRight,Clock3,Users,CircleAlert,MoreHorizontal,Command,LogOut,Grip,CalendarDays,ArrowRight,PanelLeftClose,Activity,Paperclip,Send,Check,MoveRight,List,LayoutGrid,House,Inbox,Settings,Layers3,ChevronRight,CircleDot,Package,ClipboardList} from '@lucide/vue'
const api=axios.create({baseURL:'/api'});api.interceptors.request.use(c=>{const t=localStorage.getItem('hetu_token');if(t)c.headers.Authorization=`Bearer ${t}`;return c})
const markdown=new MarkdownIt({breaks:true,linkify:true});const renderMarkdown=value=>DOMPurify.sanitize(markdown.render(value||''))
const richContent=value=>{const source=String(value||'');const html=/<\/?(p|h[1-6]|ul|ol|li|strong|em|blockquote|table|div|img|a|br)(\s|>|\/)/i.test(source)?source:markdown.render(source);return DOMPurify.sanitize(html)}
echarts.use([BarChart,LineChart,GridComponent,TooltipComponent,CanvasRenderer])
const token=ref(localStorage.getItem('hetu_token')||'');const sidebarCollapsed=ref(false);const route=ref('projectOverview');const boardMode=ref('list');const loading=ref(false);const dashboard=ref({});const projects=ref([]),tasks=ref([]),requirements=ref([]),bugs=ref([]);const chartEl=ref(null);const expandedTaskId=ref(null);let chart
const recordDetailOpen=ref(false),recordDetailKind=ref('requirement'),recordDetailItem=ref(null)
const user=ref('项目成员');const todayLabel=new Date().toLocaleDateString('en-US',{weekday:'long',month:'long',day:'numeric',year:'numeric'}).toUpperCase();const roles=ref([]);const permissions=ref([]);const roleNames={hetu_pm:'产品经理',hetu_director:'技术总监',hetu_developer:'开发人员',hetu_tester:'测试人员',hetu_ops:'运维工程师',admin:'系统管理员',common:'普通用户'};const roleLabel=computed(()=>roles.value.map(r=>roleNames[r]).filter(Boolean).join(' / ')||'项目成员');const isAdmin=computed(()=>roles.value.includes('admin'));const can=permission=>isAdmin.value||permissions.value.includes(permission);const allowedPages=computed(()=>{if(isAdmin.value||roles.value.includes('hetu_director'))return ['overview','projects','tasks','requirements','bugs','analytics'];if(roles.value.includes('hetu_pm'))return ['overview','projects','tasks','requirements','analytics'];if(roles.value.includes('hetu_tester'))return ['overview','projects','tasks','bugs','analytics'];return ['overview','projects','tasks','bugs']});const activeProject=ref('全部项目');const search=ref('');const dialog=ref(false),dialogType=ref('task'),saving=ref(false),reqPreview=ref(false);const form=reactive({});const requirementEditor=ref(null);let pendingRequirementImages=[];const toast=(msg,type='success')=>ElMessage({message:msg,type,duration:2200})
const login=reactive({username:'admin',password:'admin123'});const fetchCaptcha=async()=>{}
async function signIn(){try{loading.value=true;const{data}=await api.post('/login',{username:login.username,password:login.password});token.value=data.token;localStorage.setItem('hetu_token',data.token);localStorage.setItem('hetu_user',login.username);await refresh()}catch(e){toast(e.response?.data?.msg||'登录失败，请检查账号和密码','error')}finally{loading.value=false}}
function signOut(){localStorage.removeItem('hetu_token');token.value='';fetchCaptcha()}
async function getList(path){const{data}=await api.get(`/hetu/${path}`);return data.data||[]}
async function refresh(){if(!token.value)return;loading.value=true;try{const results=await Promise.all([api.get('/hetu/dashboard'),getList('projects'),getList('tasks'),getList('requirements'),getList('bugs'),api.get('/getInfo')]);if(results.some(r=>r.data?.code===401)){signOut();toast('登录已过期，请重新登录','warning');return}dashboard.value=results[0].data.data||{};projects.value=results[1];tasks.value=results[2];requirements.value=results[3];bugs.value=results[4];user.value=results[5].data.user?.nickName||results[5].data.user?.userName||'项目成员';roles.value=results[5].data.roles||[];permissions.value=results[5].data.permissions||[];if(!projects.value.some(p=>p.name===activeProject.value))activeProject.value=projects.value[0]?.name||'全部项目';await nextTick();drawChart()}catch(e){if(e.response?.status===401){signOut()}else toast(e.response?.data?.msg||'连接失败，请确认后端与数据库已启动','error')}finally{loading.value=false}}
function drawChart(){if(!chartEl.value)return;chart?.dispose();chart=echarts.init(chartEl.value);const trend=dashboard.value.bugTrend||[];const contrib=dashboard.value.contributions||[];chart.setOption({grid:[{left:44,right:'55%',top:28,bottom:30},{left:'58%',right:26,top:28,bottom:30}],tooltip:{trigger:'axis',backgroundColor:'#192435',borderWidth:0,textStyle:{color:'#fff'}},xAxis:[{type:'category',gridIndex:0,boundaryGap:false,data:trend.map(x=>x.day)},{type:'category',gridIndex:1,data:contrib.map(x=>x.actor),axisLabel:{interval:0,color:'#758196'}}],yAxis:[{type:'value',gridIndex:0,splitLine:{lineStyle:{color:'#edf0f5'}},axisLabel:{color:'#9ba5b4'}},{type:'value',gridIndex:1,splitLine:{show:false},axisLabel:{show:false}}],series:[{name:'新增缺陷',type:'line',smooth:true,symbolSize:7,data:trend.map(x=>x.count),xAxisIndex:0,yAxisIndex:0,lineStyle:{color:'#6c7ef5',width:3},itemStyle:{color:'#6c7ef5'},areaStyle:{color:'rgba(108,126,245,.12)'}},{name:'贡献工时',type:'bar',barWidth:18,data:contrib.map(x=>x.hours),xAxisIndex:1,yAxisIndex:1,itemStyle:{color:'#39c6a5',borderRadius:[6,6,0,0]}}]})}
onMounted(()=>{if(token.value)refresh();else fetchCaptcha();window.addEventListener('resize',resize);window.addEventListener('hetu-refresh',refresh)});onUnmounted(()=>{window.removeEventListener('resize',resize);window.removeEventListener('hetu-refresh',refresh);chart?.dispose()});function resize(){chart?.resize()}
const nav=[{key:'overview',label:'工作台',icon:House},{key:'todo',label:'我的待办',icon:Inbox,badge:computed(()=>personalTasks.value.filter(t=>t.status!=='DONE').length)},{key:'projectOverview',label:'项目概览',icon:LayoutDashboard},{key:'requirements',label:'需求',icon:FileText},{key:'tasks',label:'任务看板',icon:CheckSquare,badge:computed(()=>projectTasks(activeProjectId.value).filter(t=>t.status!=='DONE').length)},{key:'taskPool',label:'任务池',icon:Layers3},{key:'testing',label:'正在测试',icon:Check},{key:'worklog',label:'工时与排名',icon:Clock3},{key:'bugs',label:'缺陷',icon:Bug,badge:computed(()=>projectBugs.value.filter(b=>b.status!=='CLOSED').length)},{key:'quality',label:'质量清单',icon:Activity},{key:'releases',label:'发布计划',icon:Package},{key:'analytics',label:'报表 / 统计',icon:ChartNoAxesCombined}];const corePages=computed(()=>{if(isAdmin.value||roles.value.includes('hetu_director'))return ['taskPool','testing','worklog','quality','releases'];if(roles.value.includes('hetu_pm'))return ['worklog','quality','releases'];if(roles.value.includes('hetu_tester'))return ['taskPool','testing','worklog','quality','releases'];if(roles.value.includes('hetu_ops'))return ['releases'];if(roles.value.includes('hetu_developer'))return ['taskPool','worklog'];return []});const visibleNav=computed(()=>nav.filter(n=>n.key==='todo'||n.key==='overview'||n.key==='projectOverview'||allowedPages.value.includes(n.key)||corePages.value.includes(n.key)));const routeLabel=computed(()=>nav.find(n=>n.key===route.value)?.label||'项目空间')
const todo=computed(()=>tasks.value.filter(t=>t.status==='TODO')),doing=computed(()=>tasks.value.filter(t=>t.status==='IN_PROGRESS')),testing=computed(()=>tasks.value.filter(t=>t.status==='TESTING')),done=computed(()=>tasks.value.filter(t=>t.status==='DONE'));const projectTasks=id=>tasks.value.filter(t=>String(t.projectId)===String(id));const activeProjectObject=computed(()=>projects.value.find(p=>p.name===activeProject.value)||projects.value[0]||null);const activeProjectId=computed(()=>activeProjectObject.value?.id);const currentProjectTasks=computed(()=>activeProjectId.value?projectTasks(activeProjectId.value):[]);const projectBugs=computed(()=>bugs.value.filter(b=>{const task=tasks.value.find(t=>String(t.id)===String(b.taskId));return !activeProjectId.value||String(task?.projectId)===String(activeProjectId.value)}));const projectRequirements=computed(()=>requirements.value.filter(r=>!activeProjectId.value||String(r.projectId)===String(activeProjectId.value)));const personalTasks=computed(()=>tasks.value.filter(t=>[t.assignee,t.owner].some(name=>String(name||'').trim().toLowerCase()===user.value.toLowerCase())));function projectPeople(project){if(!project)return[];const pid=String(project.id);const names=[project.owner,...tasks.value.filter(t=>String(t.projectId)===pid).map(t=>t.assignee),...requirements.value.filter(r=>String(r.projectId)===pid).map(r=>r.owner)];return [...new Set(names.map(x=>String(x||'').trim()).filter(Boolean))]}const projectMembers=computed(()=>projectPeople(activeProjectObject.value).length);const projectProgress=id=>{const rows=projectTasks(id);return rows.length?Math.round(rows.reduce((s,t)=>s+Number(t.progress||0),0)/rows.length):0};const statusCounts=computed(()=>[{key:'DONE',label:'已完成',color:'#45bd91',count:currentProjectTasks.value.filter(t=>t.status==='DONE').length},{key:'IN_PROGRESS',label:'进行中',color:'#5689f6',count:currentProjectTasks.value.filter(t=>t.status==='IN_PROGRESS').length},{key:'TODO',label:'未开始',color:'#b5bdce',count:currentProjectTasks.value.filter(t=>t.status==='TODO').length},{key:'TESTING',label:'待测试',color:'#f5b64d',count:currentProjectTasks.value.filter(t=>t.status==='TESTING').length}]);const statusDonut=computed(()=>{const total=statusCounts.value.reduce((n,s)=>n+s.count,0)||1;let cursor=0;return `conic-gradient(${statusCounts.value.map(s=>{const start=cursor;cursor+=s.count/total*100;return `${s.color} ${start}% ${cursor}%`}).join(',')})`});const daysLeft=d=>{if(!d)return'未设置';let n=Math.ceil((new Date(d)-new Date())/86400000);return n<0?`延期 ${-n} 天`:n===0?'今天截止':`${n} 天后`};const fmt=n=>Number(n||0).toLocaleString('zh-CN');const visibleTasks=computed(()=>tasks.value.filter(t=>(activeProject.value==='全部项目'||projects.value.find(p=>String(p.id)===String(t.projectId))?.name===activeProject.value)&&(!search.value||t.title?.toLowerCase().includes(search.value.toLowerCase()))))
function openForm(type,item=null){const key={project:'project',task:'task',requirement:'requirement',bug:'bug'}[type];if(!can(`hetu:${key}:${item?'edit':'add'}`)){toast('当前角色没有此操作权限','warning');return}pendingRequirementImages=[];reqPreview.value=false;dialogType.value=type;Object.keys(form).forEach(k=>delete form[k]);Object.assign(form,item?{...item}:{status:type==='task'?'TODO':type==='bug'?'NEW':type==='requirement'?'DRAFT':'ACTIVE',priority:'MEDIUM',progress:0,estimateHours:8,projectId:activeProjectId.value||projects.value[0]?.id,assignee:type==='task'?'':user.value,owner:user.value,severity:'MEDIUM',rootCause:'NO_DEDUCTION',type:'FUNCTIONAL',version:type==='requirement'?'v1.0':'',content:type==='requirement'?'<h2>背景</h2><p><br></p><h2>目标</h2><p><br></p><h2>验收标准</h2><ul><li><br></li></ul>':''});if(type==='requirement'&&item)form.content=richContent(item.content);dialog.value=true}
function openRecordDetail(kind,item){recordDetailKind.value=kind;recordDetailItem.value=item;recordDetailOpen.value=true}
const recordDetailCanEdit=computed(()=>{const permission={requirement:'hetu:requirement:edit',task:'hetu:task:edit',bug:'hetu:bug:edit'}[recordDetailKind.value];return Boolean(permission&&can(permission))})
const recordDetailProjectName=computed(()=>{let projectId=recordDetailItem.value?.projectId;if(recordDetailKind.value==='bug'){const task=tasks.value.find(t=>String(t.id)===String(recordDetailItem.value?.taskId));projectId=task?.projectId}return projects.value.find(p=>String(p.id)===String(projectId))?.name||'未关联项目'})
const recordDetailTask=computed(()=>tasks.value.find(t=>String(t.id)===String(recordDetailItem.value?.taskId))||null)
const recordDetailRequirement=computed(()=>{const requirementId=recordDetailKind.value==='task'?recordDetailItem.value?.requirementId:recordDetailTask.value?.requirementId;return requirements.value.find(r=>String(r.id)===String(requirementId))||null})
function editRecordDetail(){const item=recordDetailItem.value;const kind=recordDetailKind.value;recordDetailOpen.value=false;openForm(kind,item)}
function handleCreateCommand(type){openForm(type)}
function createBugForTask(task){openForm('bug');if(dialog.value){form.taskId=task.id;form.projectId=task.projectId;form.assignee=task.assignee||''}}
async function assignBug(bug){try{const{value:assignee}=await ElMessageBox.prompt('输入负责修复此缺陷的成员姓名。','分派缺陷',{inputValue:bug.assignee||'',inputPlaceholder:'负责人姓名',confirmButtonText:'确认分派',cancelButtonText:'取消'});await api.post(`/hetu/bugs/${bug.id}/assign`,{assignee});toast('责任人已更新');await refresh()}catch(e){if(e==='cancel'||e==='close')return;toast(e.response?.data?.msg||'分派失败','error')}}
async function saveForm(){
  if(!form.title&&!form.name){toast('请先填写名称','warning');return}
  saving.value=true
  const types={project:'projects',task:'tasks',requirement:'requirements',bug:'bugs'},path=types[dialogType.value],id=form.id
  let imageUploadFailed=false
  try{
    if(id) await api.put(`/hetu/${path}/${id}`,form)
    else {
      const{data}=await api.post(`/hetu/${path}`,form)
      if(dialogType.value==='requirement'&&pendingRequirementImages.length){
        const requirementId=data.data?.id
        if(requirementId){
          for(const pending of pendingRequirementImages){
            try{const url=await uploadRequirementImage(pending.file,requirementId);form.content=form.content.replace(pending.token,`<img src="${url}" alt="需求截图">`)}
            catch(e){imageUploadFailed=true;form.content=form.content.replace(pending.token,'')}
          }
          await api.put(`/hetu/requirements/${requirementId}`,form)
        }
      }
    }
    toast(imageUploadFailed?'需求已保存，但有图片上传失败':'已创建')
    dialog.value=false;pendingRequirementImages=[];await refresh()
  }catch(e){toast(e.response?.data?.msg||'保存失败','error')}
  finally{saving.value=false}
}
async function transitionStatus(kind,item,status){if(kind==='task'&&status==='TESTING'&&Number(item.progress)<100){toast('开发进度达到 100% 后才能提交测试','warning');return}const noteNeeded=(kind==='requirement'&&status==='APPROVED')||(kind==='task'&&status==='IN_PROGRESS'&&item.status==='TESTING');let note='';if(noteNeeded){try{const result=await ElMessageBox.prompt(kind==='requirement'?'填写需求澄清结论':'填写测试退回原因',kind==='requirement'?'确认需求':'退回开发',{inputType:'textarea',inputPlaceholder:'填写本次说明',confirmButtonText:'确认',cancelButtonText:'取消'});note=result.value||''}catch(e){if(e==='cancel'||e==='close')return;throw e}}try{await api.patch(`/hetu/${kind==='requirement'?'requirements':kind==='bug'?'bugs':'tasks'}/${item.id}/status`,{status,note});toast('状态已更新');await refresh()}catch(e){toast(e.response?.data?.msg||'状态更新失败','error')}}
const moveTask=(task,status)=>transitionStatus('task',task,status)
async function updateProgress(task){try{const{value}=await ElMessageBox.prompt('更新累计完成百分比（0–100）','更新进度',{inputValue:String(task.progress||0),inputPattern:/^(100|[1-9]?\d)$/,inputErrorMessage:'请输入 0 到 100 的整数',confirmButtonText:'保存',cancelButtonText:'取消'});await api.patch(`/hetu/tasks/${task.id}/progress`,{progress:Number(value),note:'工作台进度更新'});toast('进度已更新');await refresh()}catch(e){if(e==='cancel'||e==='close')return;toast(e.response?.data?.msg||'更新失败','error')}}
async function uploadRequirementImage(file,requirementId){const payload=new FormData();payload.append('file',file,file.name||'screenshot.png');const{data}=await api.post('/hetu/attachments',payload,{params:{entityType:'requirement',entityId:requirementId}});return data.data.url}
async function pasteRichImage(file){if(dialogType.value!=='requirement')return;if(!form.id){const token=`__HETU_IMAGE_${crypto.randomUUID().replaceAll('-','')}__`;pendingRequirementImages.push({file,token});requirementEditor.value?.insertHtml(`<span>${token}</span>`);toast('图片将在保存需求时上传');return}try{const url=await uploadRequirementImage(file,form.id);requirementEditor.value?.insertHtml(`<img src="${url}" alt="需求截图">`);toast('截图已上传并插入需求正文')}catch(e){toast(e.response?.data?.msg||'图片上传失败','error')}}
function dragStart(e,task){e.dataTransfer.setData('task',String(task.id))}async function dropTask(e,status){const id=Number(e.dataTransfer.getData('task'));const t=tasks.value.find(x=>Number(x.id)===id);if(t)await moveTask(t,status)}
const dialogTitle=computed(()=>form.id?({project:'编辑项目',task:'编辑任务',requirement:'编辑需求',bug:'编辑缺陷'}[dialogType.value]):({project:'新建项目',task:'创建任务',requirement:'编写需求',bug:'登记缺陷'}[dialogType.value]))

</script>

<template>
<div v-if="!token" class="login-page"><div class="login-art"><div class="art-grid"></div><img class="hero-logo" src="/hetu-logo.png" alt="河图 Hetu"/><div class="art-copy"><div class="eyebrow">HETU · TEAM WORKSPACE</div><h1>让每一次交付<br>都清晰可见。</h1><p>连接目标、团队与成果。<br>让研发协作自然流动。</p></div><div class="art-foot">PROJECTS THAT MOVE FORWARD <span>↗</span></div><div class="art-orb orb-one"></div><div class="art-orb orb-two"></div></div><div class="login-panel"><div class="login-form"><div class="mini-brand"><span class="brand-mark logo-crop"><img src="/hetu-logo.png" alt="河图"/></span><span><b>河图</b><small>研发协作平台</small></span></div><div class="login-heading"><h2>欢迎回来</h2><p>登录以继续你的工作</p></div><label>账号</label><el-input v-model="login.username" size="large" placeholder="请输入账号" @keyup.enter="signIn"/><label>密码</label><el-input v-model="login.password" type="password" show-password size="large" placeholder="请输入密码" @keyup.enter="signIn"/><el-button type="primary" size="large" class="login-btn" :loading="loading" @click="signIn">登录工作台 <ArrowRight :size="16"/></el-button><div class="login-hint">使用你的工作台账号和密码登录</div></div><div class="login-legal">© 2026 HETU WORKSPACE <span>以协作，赴山海</span></div></div></div>
<div v-else class="app-shell" :class="{'sidebar-collapsed':sidebarCollapsed}" v-loading="loading" element-loading-background="rgba(245,247,251,.68)">
<aside class="sidebar"><div class="brand"><span class="brand-mark logo-crop"><img src="/hetu-logo.png" alt="河图"/></span><span class="brand-word"><b>河图</b><small>研发协作平台</small></span><button class="collapse" :title="sidebarCollapsed?'展开侧边栏':'收起侧边栏'" @click="sidebarCollapsed=!sidebarCollapsed"><PanelLeftClose :size="17"/></button></div><div class="space-label">全局工作空间</div><div class="global-nav"><button v-for="n in visibleNav.filter(x=>['overview','todo'].includes(x.key))" :key="n.key" class="nav-item" :class="{active:route===n.key}" @click="route=n.key"><component :is="n.icon" :size="18"/><span>{{n.label}}</span><i v-if="n.badge?.value" class="nav-count">{{n.badge.value}}</i></button></div><div class="space-label project-space-label">项目空间</div><label class="workspace-switch"><span class="workspace-logo">{{activeProjectObject?.name?.slice(0,1)||'项'}}</span><select v-model="activeProject" aria-label="选择当前项目"><option v-for="p in projects" :key="p.id" :value="p.name">{{p.name}}</option></select><ChevronDown :size="15"/></label><nav class="project-nav"><button v-for="n in visibleNav.filter(x=>!['overview','todo'].includes(x.key))" :key="n.key" class="nav-item" :class="{active:route===n.key}" @click="route=n.key"><component :is="n.icon" :size="18"/><span>{{n.label}}</span><i v-if="n.badge?.value" class="nav-count">{{n.badge.value}}</i></button></nav><div class="sidebar-bottom"><button class="settings-link" @click="route='projects'"><Settings :size="17"/>项目设置</button><button class="settings-link collapse-link" @click="sidebarCollapsed=!sidebarCollapsed"><PanelLeftClose :size="17"/>{{sidebarCollapsed?'展开侧边栏':'收起侧边栏'}}</button><button class="user-row" @click="signOut"><div class="avatar avatar-purple">{{user.slice(0,1)}}</div><span><b>{{user}}</b><small>{{roleLabel}}</small></span><LogOut :size="16"/></button></div></aside>
<main class="main"><header class="topbar"><div class="crumb"><span>{{route==='overview'||route==='todo'?'我的工作':`项目空间　›　${activeProjectObject?.name||'尚无项目'}`}}</span><MoveRight :size="14"/><b>{{routeLabel}}</b></div><div class="top-actions"><div class="search-box"><Search :size="16"/><input v-model="search" placeholder="搜索需求、任务、缺陷…"/><kbd>⌘ K</kbd></div><el-dropdown v-if="route!=='overview'&&route!=='todo'" trigger="click" @command="handleCreateCommand"><el-button type="primary" class="top-create"><Plus :size="16"/> 新建 <ChevronDown :size="14"/></el-button><template #dropdown><el-dropdown-menu><el-dropdown-item v-if="can('hetu:requirement:add')" command="requirement">创建需求</el-dropdown-item><el-dropdown-item v-if="can('hetu:task:add')" command="task">创建任务</el-dropdown-item><el-dropdown-item v-if="can('hetu:bug:add')" command="bug">登记缺陷</el-dropdown-item></el-dropdown-menu></template></el-dropdown><button class="icon-button notify" aria-label="通知"><Bell :size="18"/><i></i></button><div class="top-avatar">{{user.slice(0,1)}}</div></div></header>
<div class="content project-content" v-if="route==='projectOverview'"><template v-if="activeProjectObject"><section class="project-hero"><div class="project-identity"><div class="project-symbol symbol-violet">{{activeProjectObject.name?.slice(0,1)}}</div><div class="project-title"><div class="title-line"><h1>{{activeProjectObject.name}}</h1><span class="status-pill status-active"><i></i>{{activeProjectObject.status==='ACTIVE'?'进行中':activeProjectObject.status==='DONE'?'已完成':'规划中'}}</span></div><p>{{activeProjectObject.description||'让需求、任务和质量反馈在同一个项目空间里持续推进。'}}</p><div class="project-meta-line"><span><Layers3 :size="14"/>{{activeProjectObject.currentStage||'研发协作'}}</span><span><CalendarDays :size="14"/>{{activeProjectObject.startDate||'未设置'}} – {{activeProjectObject.endDate||'未设置'}}</span><span><Users :size="14"/>{{projectMembers}} 位已记录参与者</span></div></div></div><div class="project-actions"><el-button v-if="can('hetu:requirement:add')" type="primary" @click="openForm('requirement')"><Plus :size="15"/>创建需求</el-button><el-button v-if="can('hetu:task:add')" @click="openForm('task')"><CheckSquare :size="15"/>创建任务</el-button><el-button v-if="can('hetu:bug:add')" @click="openForm('bug')"><Bug :size="15"/>登记缺陷</el-button></div></section><nav class="project-tabs"><button :class="{selected:route==='projectOverview'}" @click="route='projectOverview'">项目概览</button><button v-if="allowedPages.includes('requirements')" :class="{selected:route==='requirements'}" @click="route='requirements'">需求 <small>{{projectRequirements.length}}</small></button><button :class="{selected:route==='tasks'}" @click="route='tasks'">任务 <small>{{currentProjectTasks.length}}</small></button><button v-if="allowedPages.includes('bugs')" :class="{selected:route==='bugs'}" @click="route='bugs'">缺陷 <small>{{projectBugs.length}}</small></button><button v-if="allowedPages.includes('analytics')" :class="{selected:route==='analytics'}" @click="route='analytics'">报表</button><button @click="route='projects'">项目设置</button></nav><div class="overview-grid"><section class="panel cycle-card"><div class="panel-head"><div><span class="section-kicker">PROJECT DELIVERY</span><h2>项目交付进度</h2></div><span class="cycle-badge"><CircleDot :size="13"/>{{activeProjectObject.currentStage||'当前阶段'}}</span></div><div class="cycle-title"><div><b>{{activeProjectObject.currentStage||'研发协作阶段'}}</b><span>任务状态实时汇总</span></div><strong>{{projectProgress(activeProjectId)}}%</strong></div><div class="large-progress"><i :style="{width:projectProgress(activeProjectId)+'%'}"></i></div><div class="cycle-stats"><div><b>{{currentProjectTasks.length}}</b><span>总任务</span></div><div><b class="green-text">{{statusCounts[0].count}}</b><span>已完成</span></div><div><b class="blue-text">{{statusCounts[1].count}}</b><span>进行中</span></div><div><b class="amber-text">{{statusCounts[3].count}}</b><span>待测试</span></div><div><b class="red-text">{{currentProjectTasks.filter(t=>t.dueDate&&t.dueDate<new Date().toISOString().slice(0,10)&&t.status!=='DONE').length}}</b><span>已延期</span></div></div><div class="cycle-footer"><span><CalendarDays :size="14"/>项目周期</span><b>{{activeProjectObject.startDate||'未设置'}} – {{activeProjectObject.endDate||'未设置'}}</b><span>{{daysLeft(activeProjectObject.endDate)}}</span></div></section><section class="panel distribution-card"><div class="panel-head"><div><span class="section-kicker">TASK STATUS</span><h2>任务状态分布</h2></div><button class="text-link" @click="route='tasks'">查看任务 <ArrowUpRight :size="14"/></button></div><div class="distribution-body"><div class="donut" :style="{background:statusDonut}"><div><b>{{currentProjectTasks.length}}</b><span>项任务</span></div></div><div class="distribution-legend"><div v-for="s in statusCounts" :key="s.key"><i :style="{background:s.color}"></i><span>{{s.label}}</span><b>{{s.count}}</b><small>{{currentProjectTasks.length?Math.round(s.count/currentProjectTasks.length*100):0}}%</small></div></div></div></section><section class="panel my-project-tasks"><div class="panel-head"><div><span class="section-kicker">MY TASKS</span><h2>我在此项目的任务</h2></div><button class="text-link" @click="route='todo'">全部待办 <ArrowUpRight :size="14"/></button></div><div v-if="personalTasks.filter(t=>String(t.projectId)===String(activeProjectId)).length" class="project-task-list"><div v-for="t in personalTasks.filter(t=>String(t.projectId)===String(activeProjectId)).slice(0,4)" :key="t.id" class="project-task-row"><span class="task-state-icon" :class="'state-'+String(t.status).toLowerCase()"><CheckSquare :size="15"/></span><div class="task-row-title"><b>{{t.title}}</b><small>#TASK-{{t.id}} · {{t.status==='DONE'?'已完成':t.status==='TESTING'?'待测试':t.status==='IN_PROGRESS'?'进行中':'待处理'}}</small></div><div class="mini-progress"><div class="progress-track"><i :style="{width:(t.progress||0)+'%'}"></i></div><small>{{t.progress||0}}%</small></div><span class="task-date">{{t.dueDate||'未设置'}}</span></div></div><div v-else class="empty-small">当前项目还没有分配给你的任务。</div></section><section class="panel pending-card"><div class="panel-head"><div><span class="section-kicker">NEEDS ATTENTION</span><h2>待处理事项</h2></div><span class="attention-count">{{projectRequirements.filter(r=>r.status==='DRAFT').length+projectBugs.filter(b=>b.status!=='CLOSED').length}}</span></div><button class="attention-row" v-for="r in projectRequirements.filter(r=>r.status==='DRAFT').slice(0,2)" :key="'r'+r.id" @click="route='requirements'"><FileText :size="16"/><span><b>{{r.title}}</b><small>需求待澄清</small></span><ChevronRight :size="15"/></button><button class="attention-row" v-for="b in projectBugs.filter(b=>b.status!=='CLOSED').slice(0,3)" :key="'b'+b.id" @click="route='bugs'"><Bug :size="16"/><span><b>{{b.title}}</b><small>缺陷{{b.status==='VERIFYING'?'待验证':b.status==='IN_PROGRESS'?'处理中':'待处理'}}</small></span><ChevronRight :size="15"/></button><div v-if="!projectRequirements.some(r=>r.status==='DRAFT')&&!projectBugs.some(b=>b.status!=='CLOSED')" class="empty-small">暂无待处理事项</div></section><section class="panel progress-list-card"><div class="panel-head"><div><span class="section-kicker">WORK ITEMS</span><h2>项目任务进展</h2></div><button class="text-link" @click="route='tasks'">任务看板 <ArrowUpRight :size="14"/></button></div><div v-for="t in currentProjectTasks.slice(0,4)" :key="t.id" class="work-item-row"><span class="work-dot" :class="'work-'+String(t.status).toLowerCase()"></span><div><b>{{t.title}}</b><small>{{t.assignee||'未分配'}} · {{t.status==='DONE'?'已完成':t.status==='TESTING'?'待测试':t.status==='IN_PROGRESS'?'进行中':'待处理'}}</small></div><span class="work-progress">{{t.progress||0}}%</span></div><div v-if="!currentProjectTasks.length" class="empty-small">创建任务后，项目进展会显示在这里。</div></section><section class="panel release-card"><div class="panel-head"><div><span class="section-kicker">VERSION PLAN</span><h2>版本规划</h2></div><Package :size="17" class="release-icon"/></div><div v-for="version in [...new Set(projectRequirements.map(r=>r.version).filter(Boolean))].slice(0,3)" :key="version" class="version-row"><span><Package :size="14"/><b>{{version}}</b></span><small>{{projectRequirements.filter(r=>r.version===version).length}} 项需求关联</small></div><div v-if="!projectRequirements.some(r=>r.version)" class="release-empty"><span>尚无需求关联版本</span><small>可在需求条目中填写版本，形成轻量发布计划。</small></div></section></div><section class="related-projects"><div class="panel-head"><div><span class="section-kicker">YOUR WORKSPACES</span><h2>相关项目</h2></div><button class="text-link" @click="route='projects'">全部项目 <ArrowUpRight :size="14"/></button></div><div class="related-list"><button v-for="(p,i) in projects" :key="p.id" class="related-project" :class="{current:p.id===activeProjectId}" @click="activeProject=p.name;route='projectOverview'"><span class="related-mark" :class="['symbol-violet','symbol-blue','symbol-mint'][i%3]">{{p.name?.slice(0,1)}}</span><span class="related-name"><b>{{p.name}}</b><small>{{p.status==='ACTIVE'?'进行中':'规划中'}}</small></span><span class="related-progress"><i><b :style="{width:projectProgress(p.id)+'%'}"></b></i><small>{{projectProgress(p.id)}}%</small></span></button><button v-if="can('hetu:project:add')" class="related-add" @click="openForm('project')"><Plus :size="16"/>新建项目</button></div></section></template><div v-else class="empty-state project-empty"><FolderKanban :size="30"/><b>还没有项目空间</b><span>创建项目后，即可在这里查看项目协作总览。</span><el-button v-if="can('hetu:project:add')" type="primary" @click="openForm('project')">创建项目</el-button></div></div>
<div class="content" v-if="route==='overview'"><div class="page-head"><div><div class="eyebrow muted">{{todayLabel}} <span class="live-dot"></span> 个人工作台</div><h1>我的工作，{{user}} <span class="wave">✳</span></h1><p>把注意力放在重要的事上，团队正在稳步向前。</p></div><el-button v-if="can('hetu:task:add')" type="primary" class="primary-action" @click="openForm('task')"><Plus :size="17"/> 新建任务</el-button></div>
<div class="stat-grid"><div class="stat-card"><div class="stat-head"><span class="stat-icon indigo"><FolderKanban :size="18"/></span><span class="stat-trend">{{fmt(dashboard.newProjectsThisMonth)}} 本月新增</span></div><div class="stat-value">{{fmt(dashboard.activeProjects)}}</div><div class="stat-label">进行中的项目 <span>↗</span></div><div class="stat-foot">共 {{projects.length}} 个项目空间</div></div><div class="stat-card"><div class="stat-head"><span class="stat-icon teal"><CheckSquare :size="18"/></span><span class="stat-trend">当前数据</span></div><div class="stat-value">{{fmt(dashboard.openTasks)}}</div><div class="stat-label">未完成任务</div><div class="stat-foot">{{done.length}} 项已顺利完成</div></div><div class="stat-card"><div class="stat-head"><span class="stat-icon amber"><Clock3 :size="18"/></span><span class="stat-alert" v-if="dashboard.overdueTasks">需要关注</span><span class="stat-trend" v-else>状态良好</span></div><div class="stat-value">{{fmt(dashboard.overdueTasks)}}</div><div class="stat-label">延期任务</div><div class="stat-foot">保持节奏，及时同步</div></div><div class="stat-card"><div class="stat-head"><span class="stat-icon rose"><Bug :size="18"/></span><span class="stat-trend">未关闭</span></div><div class="stat-value">{{fmt(dashboard.openBugs)}}</div><div class="stat-label">待处理缺陷</div><div class="stat-foot">质量反馈持续跟进</div></div></div>
<section class="section-block"><div class="section-title"><div><span class="section-kicker">IN FOCUS</span><h2>项目进展</h2></div><button class="text-link" @click="route='projects'">查看全部 <ArrowUpRight :size="15"/></button></div><div class="project-grid"><article v-for="(p,i) in projects.slice(0,3)" :key="p.id" class="project-card" @click="activeProject=p.name;route='tasks'"><div class="project-top"><div class="project-symbol" :class="['symbol-violet','symbol-blue','symbol-mint'][i%3]">{{p.name?.slice(0,1)}}</div><button class="more"><MoreHorizontal :size="19"/></button></div><div class="project-meta">{{p.code}} <span class="priority" :class="`priority-${String(p.priority||'').toLowerCase()}`">{{p.priority==='HIGH'?'高优先级':p.priority==='LOW'?'低优先级':'常规'}}</span></div><h3>{{p.name}}</h3><p class="project-desc">{{p.description||'暂无项目描述'}}</p><div class="project-progress-head"><span>项目进度</span><b>{{projectProgress(p.id)}}%</b></div><div class="progress-track"><i :style="{width:projectProgress(p.id)+'%'}"></i></div><div class="project-bottom"><div class="avatar-stack"><span v-for="(name,memberIndex) in projectPeople(p).slice(0,4)" :key="name" class="avatar" :class="['avatar-purple','avatar-blue','avatar-green'][memberIndex%3]">{{name.slice(0,1)}}</span><small v-if="projectPeople(p).length>4">+{{projectPeople(p).length-4}}</small><small v-if="!projectPeople(p).length">暂无成员</small></div><span class="due-label"><CalendarDays :size="14"/> {{daysLeft(p.endDate)}}</span></div></article><button v-if="can('hetu:project:add')" class="new-project-card" @click="openForm('project')"><span><Plus :size="19"/></span><b>创建新项目</b><small>开启一次新的协作</small></button></div></section>
<div class="lower-grid"><section class="panel chart-panel"><div class="panel-head"><div><span class="section-kicker">TEAM PULSE</span><h2>团队节奏</h2></div><span class="stat-foot">缺陷近 7 天 · 工时近 30 天</span></div><div class="chart-legend"><span><i class="legend-dot purple-dot"></i>缺陷趋势</span><span><i class="legend-dot green-dot"></i>贡献工时（近 30 天）</span></div><div ref="chartEl" class="chart-area"></div></section><section class="panel focus-panel"><div class="panel-head"><div><span class="section-kicker">UP NEXT</span><h2>今日待办</h2></div><button class="text-link" @click="route='tasks'">全部任务 <ArrowUpRight :size="15"/></button></div><div v-if="tasks.filter(t=>t.status!=='DONE').slice(0,4).length" class="todo-list"><div v-for="t in tasks.filter(t=>t.status!=='DONE').slice(0,4)" :key="t.id" class="todo-row"><button class="todo-check" :title="t.status==='IN_PROGRESS'?'更新进度并记录贡献工时':t.status==='TESTING'?'测试通过':'开始任务'" :aria-label="t.status==='IN_PROGRESS'?'更新进度':t.status==='TESTING'?'测试通过':'开始任务'" @click="t.status==='IN_PROGRESS'?updateProgress(t):moveTask(t,t.status==='TESTING'?'DONE':'IN_PROGRESS')"><Check :size="13"/></button><div class="todo-text"><b>{{t.title}}</b><small>{{t.assignee||'未分配'}} · {{daysLeft(t.dueDate)}}</small></div><span class="todo-priority" :class="`p-${String(t.priority||'').toLowerCase()}`">{{t.priority==='HIGH'?'高':t.priority==='LOW'?'低':'中'}}</span></div></div><div v-else class="empty-small">今天的任务已清空，做得不错。</div></section></div>
</div>
<div class="content" v-else-if="route==='todo'"><div class="page-head compact"><div><div class="eyebrow muted">PERSONAL INBOX</div><h1>我的待办</h1><p>只看分配给{{user}}的任务，快速找到下一步。</p></div></div><div class="data-panel"><div class="table-head task-list-head"><span>任务</span><span>所属项目</span><span>截止日期</span><span>进度</span><span>状态</span></div><div v-for="t in personalTasks" :key="t.id" class="task-list-row"><span class="req-title"><span class="req-icon"><CheckSquare :size="16"/></span><b>{{t.title}}</b></span><span>{{projects.find(p=>String(p.id)===String(t.projectId))?.name||'未关联项目'}}</span><span>{{t.dueDate||'未设置'}}</span><span class="list-progress"><span class="progress-track"><i :style="{width:(t.progress||0)+'%'}"></i></span>{{t.progress||0}}%</span><span><i class="status-pill" :class="`status-${String(t.status).toLowerCase()}`">{{t.status==='DONE'?'已完成':t.status==='TESTING'?'待测试':t.status==='IN_PROGRESS'?'进行中':'待处理'}}</i></span></div><div v-if="!personalTasks.length" class="empty-state"><Inbox :size="24"/><b>暂时没有分配给你的任务</b><span>项目负责人分配任务后，会显示在这里。</span></div></div></div>
<div class="content" v-else-if="route==='tasks'"><div class="page-head compact"><div><div class="eyebrow muted">DELIVERY TRACKER</div><h1>任务看板</h1><p>让每个下一步都清楚，让进展自然发生。</p></div><div class="head-actions"><el-select v-model="activeProject" class="project-select"><el-option label="全部项目" value="全部项目"/><el-option v-for="p in projects" :key="p.id" :label="p.name" :value="p.name"/></el-select><el-button v-if="can('hetu:task:add')" type="primary" class="primary-action" @click="openForm('task')"><Plus :size="17"/> 新建任务</el-button></div></div><div class="board-toolbar"><span><span class="live-dot"></span> {{visibleTasks.length}} 项任务</span><div class="toolbar-right"><div class="avatar-stack tiny-stack"><span v-for="(name,memberIndex) in [...new Set(visibleTasks.map(t=>t.assignee).filter(Boolean))].slice(0,4)" :key="name" class="avatar" :class="['avatar-purple','avatar-blue','avatar-green'][memberIndex%3]">{{name.slice(0,1)}}</span><small v-if="new Set(visibleTasks.map(t=>t.assignee).filter(Boolean)).size>4">+{{new Set(visibleTasks.map(t=>t.assignee).filter(Boolean)).size-4}}</small><small v-if="!visibleTasks.some(t=>t.assignee)">暂无负责人</small></div><div class="view-switch"><button :class="{selected:boardMode==='board'}" @click="boardMode='board'"><LayoutGrid :size="14"/></button><button :class="{selected:boardMode==='list'}" @click="boardMode='list'"><List :size="14"/></button></div></div></div><div v-if="boardMode==='board'" class="board"><div v-for="col in [{key:'TODO',title:'待处理',rows:visibleTasks.filter(t=>t.status==='TODO'),color:'gray'},{key:'IN_PROGRESS',title:'进行中',rows:visibleTasks.filter(t=>t.status==='IN_PROGRESS'),color:'blue'},{key:'TESTING',title:'待测试',rows:visibleTasks.filter(t=>t.status==='TESTING'),color:'amber'},{key:'DONE',title:'已完成',rows:visibleTasks.filter(t=>t.status==='DONE'),color:'green'}]" :key="col.key" class="board-column" @dragover.prevent @drop="dropTask($event,col.key)"><div class="column-head"><span class="column-dot" :class="col.color"></span><b>{{col.title}}</b><span class="column-count">{{col.rows.length}}</span><button v-if="can('hetu:task:add')" @click="openForm('task')"><Plus :size="16"/></button></div><div class="task-stack"><article v-for="t in col.rows" :key="t.id" class="task-card" draggable="true" @dragstart="dragStart($event,t)"><div class="task-card-top"><span class="task-project">{{projects.find(p=>String(p.id)===String(t.projectId))?.code||'任务'}}</span><button class="table-action muted-action" @click.stop="openRecordDetail('task',t)">详情</button><button class="more" @click.stop="openRecordDetail('task',t)"><MoreHorizontal :size="17"/></button></div><h3>{{t.title}}</h3><p v-if="t.description">{{t.description}}</p><div class="mini-progress"><div class="progress-track"><i :style="{width:(t.progress||0)+'%'}"></i></div><small>{{t.progress||0}}%</small><button @click.stop="updateProgress(t)">更新</button></div><div class="task-tags"><span class="tag" :class="`priority-${String(t.priority||'').toLowerCase()}`">{{t.priority==='HIGH'?'高优先级':t.priority==='LOW'?'低优先级':'常规'}}</span><span v-if="t.bugCount" class="bug-tag"><Bug :size="12"/> {{t.bugCount}}</span></div><div class="task-card-bottom"><div class="assignee"><span class="avatar avatar-blue">{{t.assignee?.slice(0,1)||'?'}}</span><small>{{t.assignee||'未分配'}}</small></div><span class="due-label" :class="{'late':String(t.dueDate)<new Date().toISOString().slice(0,10)}"><CalendarDays :size="13"/>{{t.dueDate||'未设置'}}</span></div><div class="task-flow"><button v-if="t.status==='TODO'" @click="moveTask(t,'IN_PROGRESS')">开始 <ArrowRight :size="12"/></button><button v-if="t.status==='IN_PROGRESS'" @click="updateProgress(t)">更新进度</button><button v-if="t.status==='IN_PROGRESS'&&Number(t.progress)===100" @click="moveTask(t,'TESTING')">提交测试</button><button v-if="t.status==='TESTING'" @click="moveTask(t,'DONE')">测试通过 ✓</button><button v-if="t.status==='TESTING'" @click="moveTask(t,'IN_PROGRESS')">退回开发</button><button v-if="t.status==='DONE'" @click="moveTask(t,'IN_PROGRESS')">重新打开</button></div></article><button v-if="can('hetu:task:add')" class="add-card" @click="openForm('task')"><Plus :size="15"/> 添加任务</button></div></div></div><div v-else class="data-panel task-list-panel"><div class="table-head task-list-head"><span>任务</span><span>负责人</span><span>进度</span><span>截止日期</span><span>状态</span></div><div v-for="t in visibleTasks" :key="t.id" class="task-list-row"><button class="req-title task-title-button" @click="openRecordDetail('task',t)"><span class="req-icon"><CheckSquare :size="16"/></span><span><b>{{t.title}}</b><small>{{projects.find(p=>String(p.id)===String(t.projectId))?.name||'未关联项目'}}</small></span></button><span class="owner-cell"><i class="avatar avatar-blue">{{t.assignee?.slice(0,1)||'?'}}</i>{{t.assignee||'未分配'}}</span><span class="list-progress"><span>{{t.progress||0}}%</span><i class="progress-track"><i :style="{width:(t.progress||0)+'%'}"></i></i></span><span class="version-cell">{{t.dueDate||'未设置'}}</span><span class="task-list-state"><i class="status-pill" :class="`status-${String(t.status).toLowerCase()}`">{{t.status==='TODO'?'待处理':t.status==='IN_PROGRESS'?'进行中':t.status==='TESTING'?'待测试':'已完成'}}</i><button v-if="t.status==='TODO'" class="table-action" @click="moveTask(t,'IN_PROGRESS')">开始</button><button v-else-if="t.status==='IN_PROGRESS'" class="table-action" @click="updateProgress(t)">报进度</button><template v-else-if="t.status==='TESTING'"><button class="table-action" @click="moveTask(t,'DONE')">通过</button><button class="table-action muted-action" @click="moveTask(t,'IN_PROGRESS')">退回</button></template><button v-else class="table-action muted-action" @click="moveTask(t,'IN_PROGRESS')">重开</button><button class="table-action muted-action" @click="openRecordDetail('task',t)">详情</button></span></div><div v-if="expandedTaskId===t.id" class="task-row-detail"><b>{{t.title}}</b><p>{{t.description||'暂无任务描述'}}</p><span>关联需求：{{requirements.find(r=>String(r.id)===String(t.requirementId))?.title||'未关联'}}</span><span>预估工时：{{t.estimateHours||0}} 小时</span><span>优先级：{{t.priority==='HIGH'?'高':t.priority==='LOW'?'低':'常规'}}</span></div><div v-if="!visibleTasks.length" class="empty-state"><CheckSquare :size="22"/><b>没有匹配的任务</b></div></div></div>
<div class="content" v-else-if="route==='projects'"><div class="page-head compact"><div><div class="eyebrow muted">PORTFOLIO</div><h1>项目空间</h1><p>项目目标、阶段和交付状态，一处掌握。</p></div><el-button v-if="can('hetu:project:add')" type="primary" class="primary-action" @click="openForm('project')"><Plus :size="17"/> 新建项目</el-button></div><div class="project-list-grid"><article v-for="(p,i) in projects" :key="p.id" class="project-card project-large" @click="activeProject=p.name;route='tasks'"><div class="project-top"><div class="project-symbol" :class="['symbol-violet','symbol-blue','symbol-mint'][i%3]">{{p.name?.slice(0,1)}}</div><span class="status-pill">{{p.status==='ACTIVE'?'进行中':'已归档'}}</span></div><div class="project-meta">{{p.code}}</div><h3>{{p.name}}</h3><p class="project-desc">{{p.description||'暂无项目描述'}}</p><div class="stage-row"><span>当前阶段</span><b>{{p.stage||'需求规划'}}</b></div><div class="project-progress-head"><span>整体进度</span><b>{{projectProgress(p.id)}}%</b></div><div class="progress-track"><i :style="{width:projectProgress(p.id)+'%'}"></i></div><div class="project-bottom"><div class="avatar-stack"><span v-for="(name,memberIndex) in projectPeople(p).slice(0,4)" :key="name" class="avatar" :class="['avatar-purple','avatar-blue','avatar-green'][memberIndex%3]">{{name.slice(0,1)}}</span><small v-if="projectPeople(p).length>4">+{{projectPeople(p).length-4}}</small><small v-if="!projectPeople(p).length">暂无成员</small></div><span class="task-count">{{projectTasks(p.id).length}} 项任务 <ArrowUpRight :size="14"/></span></div></article><button v-if="can('hetu:project:add')" class="new-project-card" @click="openForm('project')"><span><Plus :size="19"/></span><b>创建新项目</b><small>开启一次新的协作</small></button></div></div>
<div class="content" v-else-if="route==='requirements'"><div class="page-head compact"><div><div class="eyebrow muted">PRODUCT BACKLOG</div><h1>需求池</h1><p>记录问题、澄清目标，让团队对价值达成共识。</p></div><el-button v-if="can('hetu:requirement:add')" type="primary" class="primary-action" @click="openForm('requirement')"><Plus :size="17"/> 编写需求</el-button></div><div class="data-panel"><div class="table-head"><span>需求条目 <b>{{projectRequirements.length}}</b></span><span>负责人</span><span>所属版本</span><span>状态</span></div><div v-for="r in projectRequirements" :key="r.id" class="requirement-row"><button class="req-title requirement-edit" @click="openRecordDetail('requirement',r)"><span class="req-icon"><FileText :size="17"/></span><span><b>{{r.title}}</b><small>{{projects.find(p=>String(p.id)===String(r.projectId))?.name||'未关联项目'}}</small></span></button><span class="owner-cell"><i class="avatar avatar-purple">{{r.owner?.slice(0,1)||'?'}}</i>{{r.owner||'未分配'}}</span><span class="version-cell">{{r.version||'未规划'}}</span><span class="requirement-actions"><i class="status-pill" :class="`req-${String(r.status).toLowerCase()}`">{{r.status==='APPROVED'?'已确认':r.status==='IN_PROGRESS'?'进行中':'待澄清'}}</i><button v-if="can('hetu:requirement:edit')&&r.status==='DRAFT'" class="table-action" @click="transitionStatus('requirement',r,'IN_PROGRESS')">澄清</button><button v-else-if="can('hetu:requirement:edit')&&r.status==='IN_PROGRESS'" class="table-action" @click="transitionStatus('requirement',r,'APPROVED')">确认需求</button><button v-else-if="can('hetu:requirement:edit')&&r.status==='APPROVED'" class="table-action muted-action" @click="transitionStatus('requirement',r,'IN_PROGRESS')">重新澄清</button></span></div><div v-if="!requirements.length" class="empty-state"><FileText :size="24"/><b>需求池还是空的</b><span>从一个清晰的问题开始吧。</span></div></div></div>
<div class="content" v-else-if="route==='bugs'"><div class="page-head compact"><div><div class="eyebrow muted">QUALITY LOOP</div><h1>缺陷跟踪</h1><p>把问题带回闭环，让质量反馈帮助交付更稳。</p></div><el-button v-if="can('hetu:bug:add')" type="primary" class="primary-action" @click="openForm('bug')"><Plus :size="17"/> 登记缺陷</el-button></div><div class="bug-summary"><div><span>未关闭缺陷</span><b>{{projectBugs.filter(b=>b.status!=='CLOSED').length}}</b></div><div><span>处理中</span><b>{{projectBugs.filter(b=>b.status==='IN_PROGRESS').length}}</b></div><div><span>待验证</span><b>{{projectBugs.filter(b=>b.status==='VERIFYING').length}}</b></div><div><span>已关闭</span><b>{{projectBugs.filter(b=>b.status==='CLOSED').length}}</b></div></div><div class="data-panel"><div class="table-head bug-head"><span>缺陷</span><span>等级</span><span>负责人</span><span>状态</span><span>操作</span></div><div v-for="b in projectBugs" :key="b.id" class="bug-row"><button class="bug-title bug-title-button" @click="openRecordDetail('bug',b)"><span class="bug-id">BUG-{{String(b.id).padStart(3,'0')}}</span><b>{{b.title}}</b><small>{{b.description||'暂无描述'}}</small></button><span class="severity" :class="`sev-${String(b.severity).toLowerCase()}`"><i></i>{{b.severity==='CRITICAL'?'致命':b.severity==='HIGH'?'严重':b.severity==='LOW'?'轻微':'一般'}}<small>{{Number(b.scoreHours)<0?`扣 ${Math.abs(Number(b.scoreHours))} 工时`:b.status==='CLOSED'?'不扣工时':'待判定'}}</small></span><span class="owner-cell"><i class="avatar avatar-blue">{{b.assignee?.slice(0,1)||'?'}}</i>{{b.assignee||'未分配'}}</span><span><i class="status-pill" :class="`bug-${String(b.status).toLowerCase()}`">{{b.status==='NEW'?'新建':b.status==='IN_PROGRESS'?'处理中':b.status==='VERIFYING'?'待验证':'已关闭'}}</i></span><span><button class="table-action muted-action" @click="openRecordDetail('bug',b)">详情</button><button v-if="can('hetu:project:edit')||can('hetu:bug:edit')" class="table-action muted-action" @click="assignBug(b)">{{b.assignee?'改派':'分派'}}</button><button v-if="b.status==='NEW' && can('hetu:bug:edit')" class="table-action" @click="transitionStatus('bug',b,'IN_PROGRESS')">开始处理</button><button v-else-if="b.status==='IN_PROGRESS' && can('hetu:bug:edit')" class="table-action" @click="transitionStatus('bug',b,'VERIFYING')">提交验证</button><span v-else-if="b.status==='VERIFYING'&&can('hetu:bug:edit')" class="requirement-actions"><button class="table-action" @click="transitionStatus('bug',b,'CLOSED')">确认关闭</button><button class="table-action muted-action" @click="transitionStatus('bug',b,'IN_PROGRESS')">退回处理</button></span><button v-else-if="b.status==='CLOSED'&&can('hetu:bug:edit')" class="table-action muted-action" @click="transitionStatus('bug',b,'NEW')">重新打开</button><button v-else-if="can('hetu:bug:edit')" class="table-action muted-action" @click="openRecordDetail('bug',b)">详情</button><span v-else class="muted">只读</span></span></div><div v-if="!projectBugs.length" class="empty-state"><Bug :size="24"/><b>暂无缺陷</b><span>质量问题会在这里形成闭环。</span></div></div></div>
<div class="content" v-else-if="route==='analytics'"><div class="page-head compact"><div><div class="eyebrow muted">INSIGHTS</div><h1>数据分析</h1><p>用团队实际进展，理解交付节奏与质量变化。</p></div></div><div class="analytics-kpis"><div class="stat-card"><span class="stat-label">项目平均完成率</span><b>{{dashboard.avgProgress||0}}%</b><div class="progress-track"><i :style="{width:(dashboard.avgProgress||0)+'%'}"></i></div></div><div class="stat-card"><span class="stat-label">累计贡献工时</span><b>{{fmt(dashboard.completedHours)}} <small>小时</small></b><div class="stat-foot">来自成员逐条登记的实际工时</div></div><div class="stat-card"><span class="stat-label">需求条目</span><b>{{requirements.length}}</b><div class="stat-foot">已确认 {{requirements.filter(r=>r.status==='APPROVED').length}} 项</div></div><div class="stat-card"><span class="stat-label">累计交付任务</span><b>{{done.length}}</b><div class="stat-foot">当前共 {{tasks.length}} 项任务</div></div></div><section class="panel chart-panel analytics-chart"><div class="panel-head"><div><span class="section-kicker">TEAM PULSE</span><h2>团队节奏与贡献</h2></div></div><div ref="chartEl" class="chart-area"></div></section></div>
<div v-if="['taskPool','worklog','testing','releases','quality'].includes(route)" class="content core-content"><CoreWorkspace :page="route" :project-id="activeProjectId" :project-name="activeProjectObject?.name||'全部项目'" :user-name="user" :can-manage-quality="can('hetu:project:edit')" :release-permissions="{add:can('hetu:release:add')||can('hetu:project:edit'),schedule:can('hetu:release:schedule'),test:can('hetu:release:test'),publish:can('hetu:release:publish'),verify:can('hetu:release:verify'),close:can('hetu:release:close'),edit:can('hetu:release:add')||can('hetu:project:edit')}" :tasks="tasks" :bugs="bugs" :requirements="requirements" @create-bug-for-task="createBugForTask"/></div>
</main>
<el-dialog v-model="dialog" :title="dialogTitle" width="560px" class="hetu-dialog" destroy-on-close><div class="form-grid" v-if="dialogType==='project'"><label>项目名称<el-input v-model="form.name" placeholder="例如：星河研发协作平台"/></label><label>项目编号<el-input v-model="form.code" placeholder="留空自动生成"/></label><label>项目负责人<el-input v-model="form.owner" placeholder="负责人姓名，留空放入任务池"/></label><label>优先级<el-select v-model="form.priority"><el-option label="高优先级" value="HIGH"/><el-option label="常规" value="MEDIUM"/><el-option label="低优先级" value="LOW"/></el-select></label><label>开始日期<el-date-picker v-model="form.startDate" type="date" value-format="YYYY-MM-DD" placeholder="选择日期"/></label><label>结束日期<el-date-picker v-model="form.endDate" type="date" value-format="YYYY-MM-DD" placeholder="选择日期"/></label><label class="full">项目描述<el-input v-model="form.description" type="textarea" :rows="3" placeholder="项目目标与背景"/></label></div><div class="form-grid" v-else-if="dialogType==='task'"><label class="full">任务标题<el-input v-model="form.title" placeholder="清楚描述要交付的结果"/></label><label>所属项目<el-select v-model="form.projectId"><el-option v-for="p in projects" :key="p.id" :label="p.name" :value="p.id"/></el-select></label><label v-if="dialogType==='task'">关联需求<el-select v-model="form.requirementId" clearable><el-option v-for="r in requirements.filter(x=>String(x.projectId)===String(form.projectId))" :key="r.id" :label="r.title" :value="r.id"/></el-select></label><label>负责人<el-input v-model="form.assignee" placeholder="负责人姓名"/></label><label>预计工时<el-input-number v-model="form.estimateHours" :min="0" :max="10000"/></label><label>截止日期<el-date-picker v-model="form.dueDate" type="date" value-format="YYYY-MM-DD" placeholder="选择日期"/></label><label>优先级<el-select v-model="form.priority"><el-option label="高" value="HIGH"/><el-option label="中" value="MEDIUM"/><el-option label="低" value="LOW"/></el-select></label><label v-if="!form.id">初始状态<el-select v-model="form.status"><el-option label="待处理" value="TODO"/><el-option label="进行中" value="IN_PROGRESS"/></el-select></label><label class="full">描述<el-input v-model="form.description" type="textarea" :rows="3" placeholder="任务说明、产出与约束"/></label></div><div class="form-grid" v-else-if="dialogType==='requirement'"><label class="full">需求标题<el-input v-model="form.title" placeholder="用一句话说明要解决的问题"/></label><label>所属项目<el-select v-model="form.projectId"><el-option v-for="p in projects" :key="p.id" :label="p.name" :value="p.id"/></el-select></label><label>负责人<el-input v-model="form.owner"/></label><label>版本<el-input v-model="form.version" placeholder="v1.0"/></label><label class="full">需求正文<RichTextEditor ref="requirementEditor" v-model="form.content" @paste-image="pasteRichImage" /></label></div><div class="form-grid" v-else><label class="full">缺陷标题<el-input v-model="form.title"/></label><label>关联任务<el-select v-model="form.taskId" clearable><el-option v-for="t in tasks" :key="t.id" :label="t.title" :value="t.id"/></el-select></label><label>负责人<el-input v-model="form.assignee"/></label><label>缺陷等级<el-select v-model="form.severity"><el-option label="致命" value="CRITICAL"/><el-option label="严重" value="HIGH"/><el-option label="一般" value="MEDIUM"/><el-option label="轻微" value="LOW"/></el-select></label><label>缺陷归因<el-select v-model="form.rootCause"><el-option label="不扣工时（默认）" value="NO_DEDUCTION"/><el-option label="开发问题（致命 50% / 严重 30% / 一般 10% / 轻微 5%，按任务预估工时）" value="PRODUCT_DEFECT"/><el-option label="需求变更（致命 5 / 严重 3 / 一般 1 / 轻微 0 工时）" value="REQUIREMENT_CHANGE"/><el-option label="环境或第三方（致命 5 / 严重 3 / 一般 1 / 轻微 0 工时）" value="ENVIRONMENT"/><el-option label="重复问题（不扣工时）" value="DUPLICATE"/><el-option label="无法复现（不扣工时）" value="NOT_REPRODUCIBLE"/></el-select></label><label>缺陷类型<el-select v-model="form.type"><el-option label="功能" value="FUNCTIONAL"/><el-option label="界面" value="UI"/><el-option label="性能" value="PERFORMANCE"/></el-select></label><label class="full">问题描述<el-input v-model="form.description" type="textarea" :rows="2"/></label><label class="full">复现步骤<el-input v-model="form.steps" type="textarea" :rows="3"/></label></div><template #footer><el-button @click="dialog=false">取消</el-button><el-button type="primary" :loading="saving" @click="saveForm">保存</el-button></template></el-dialog>
<RecordDetailDialog v-model="recordDetailOpen" :kind="recordDetailKind" :item="recordDetailItem" :project-name="recordDetailProjectName" :related-task="recordDetailTask" :related-requirement="recordDetailRequirement" :can-edit="recordDetailCanEdit" :safe-content="recordDetailKind==='requirement'?richContent(recordDetailItem?.content):''" @edit="editRecordDetail"/>
</div>
</template>
